contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take all inputs needed: from, caddress, _tos array, value v, and an amount of Ether to fund this contract
    function run(address from, address caddress, address[] calldata _tos, uint v, uint fundAmount) public payable {
        // fund this test contract if requested
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
        }

        // Observe balance of this test contract before calling c.transfer
        uint balBefore = address(this).balance;

        // Call C.transfer and capture whether it reverted and its return when not reverted
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) {
            reverted = false;
            // We cannot capture return value via try without assignment, so call again as a view is not possible.
            // Instead we assume success implies return true per contract; but to be explicit we call and assign using low-level call to capture return data.
        } catch {
            reverted = true;
        }

        // To determine the boolean return when call does not revert, perform a low-level call to the function selector
        bytes4 id = bytes4(keccak256("transfer(address,address,address[],uint256)"));
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(id, from, caddress, _tos, v));
        // ok mirrors whether it reverted; data should contain the ABI-encoded (bool)
        if (ok && data.length >= 32) {
            ret = abi.decode(data, (bool));
        } else {
            // if low-level call failed, set ret = false but mark reverted true
            ret = false;
            reverted = true;
        }

        uint balAfter = address(this).balance;

        // General rule asserted:
        // If _tos.length == 0 then transfer must revert (per require in P). Otherwise, transfer returns true iff the low-level calls inside succeed.
        // We express: if ret == true then not reverted, _tos.length>0, and this contract's balance didn't decrease. If reverted then either _tos.length==0 or at least one inner call failed.
        // We cannot observe inner calls directly, so we assert consistency between ret, reverted, _tos.length, and balance change.
        assert((ret == true) == (reverted == false && _tos.length > 0 && balAfter == balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function following the required flat shape
    function run(address from, address caddress, address[] calldata _tos, uint v, uint fundAmount) public payable {
        // optionally fund this test contract for any potential value transfers (must hold before calling C.transfer)
        if (fundAmount > 0) {
            require(address(this).balance >= fundAmount);
        }

        // Observe balance before calling c.transfer
        uint balBefore = address(this).balance;

        // Make the state-changing call as a top-level statement and capture success via try/catch
        bool callReverted;
        bool returnedTrue;
        try c.transfer(from, caddress, _tos, v) {
            callReverted = false;
            // To obtain the returned bool, perform a second top-level low-level call to capture return data
            // (This is still a top-level statement and allowed.)
            bytes4 sel = bytes4(keccak256("transfer(address,address,address[],uint256)"));
            (bool ok, bytes memory data) = address(c).call(abi.encodeWithSelector(sel, from, caddress, _tos, v));
            if (ok && data.length >= 32) {
                returnedTrue = abi.decode(data, (bool));
            } else {
                // Shouldn't happen if the try branch executed, but keep a consistent default
                returnedTrue = false;
            }
        } catch {
            callReverted = true;
            returnedTrue = false;
        }

        uint balAfter = address(this).balance;

        // General rule: if the transfer returned true (i.e., did not revert and returned true), then
        // _tos.length > 0 (contract requires non-empty) and this contract's balance did not decrease.
        assert((returnedTrue == true) == (callReverted == false && _tos.length > 0 && balAfter >= balBefore));
    }

    receive() external payable {}
}

